# INV-006 script v4: v3 + NEW rows (30-min version).
NEW = ['P1-10d', 'P1-10e', 'P1-10f', 'P1-10g', 'P2-11d', 'P2-11e', 'P2-11f', 'P2-11g', 'P2-11h', 'P4-01c', 'P4-01d', 'P4-01e', 'P4-05b', 'P4-05c', 'P4-05d', 'P4-05e', 'P5-06c', 'P5-06d', 'RC-05b', 'RC-05c', 'RC-05d', 'P2-12b', 'P2-12c', 'P5-01c', 'P5-01d', 'P5-05b', 'P5-05c', 'P5-05d', 'P5-07b', 'P5-07c', 'P5-07d', 'P5-07e', 'RC-07b', 'RC-04b', 'RC-04c', 'P3-12b', 'P4-07b', 'P1-12b']
R = [('CO-01', 'Ras Laffan, Qatar. The second of March, 2026. Two drones cross the coast, and the biggest gas export plant on Earth goes quiet.', 'F04', "AI-STILL: Ras Laffan LNG trains at dusk, flares out, slow push; HARD CUT TO BLACK on 'goes quiet', then back on the map. Label Illustration.", 'RAS LAFFAN, QATAR · 2 MAR 2026', 'REPORTED · Qatar MoD via Bloomberg', "low drone in, sub hit on 'quiet'"), ('CO-02', "That silence lands on Britain's energy price cap in January. No one in Leeds or Lyon heard the drones. They will hear the bill.", '', 'MAP-3D: camera pulls from Qatar to Europe, a thin orange line stretching.', '', '', 'whoosh-deep'), ('CO-03', 'By the twenty-fifth of November, the regulator Ofgem will put a number on it. The forecasts say twenty-three to thirty-nine pounds more for a typical home, every month.', 'F42 F43', 'CARD-NUMBER: +£23 to +£39 / month. 2 s flash of the final RECEIPT.', 'ENERGY PRICE CAP · JANUARY 2027', 'ESTIMATE · supplier and Cornwall Insight forecasts, Oct 2026', 'counter roll, receipt printer'), ('CO-04', "Some of that is a forecast, not a fact. Ofgem has not decided yet, and the forecasters disagree by almost two hundred pounds a year. We'll show you both ends.", 'F43', 'CARD-LADDER: Cornwall £1,999 vs EDF £2,189.', 'FORECASTS, NOT DECISIONS', 'ESTIMATE', 'tick'), ('CO-05', "By the end, you'll see every line on this bill. We'll follow the gas from that plant, through one strait, into Europe's half-empty tanks, past an auction where a single ship decides which way to turn, and onto your meter.", '', 'Roadmap: five icons light in a row (plant, strait, tank, gavel, meter).', 'THE DOOR · THE TANK · THE AUCTION · THE LAST TIME · YOUR TABLE', '', 'riser'), ('P1-01', 'Part one. The door.', '', 's_part: PART 1, THE DOOR.', 'PART 1 · THE DOOR', '', 'reverse cymbal + sub drop'), ('P1-02', 'Before this war, about one fifth of all the liquefied gas traded on the planet sailed through a single strait. Hormuz.', 'F01', 'G16 strait map: two glowing lanes, measure line.', '1 IN 5 LNG CARGOES', 'VERIFIED · EIA, 2024', 'whoosh-deep + scan'), ('P1-03', 'Almost all of it came from one country. Qatar shipped about nine billion cubic feet a day through that water in 2024. The Emirates added a little more.', 'F02', 'CARD-NUMBER: 9.3 Bcf/d, faded 0.7 for the UAE.', 'QATAR 9.3 · UAE 0.7 BCF/D', 'VERIFIED · EIA, 2024', 'card land'), ('P1-04', "Most of it went east. About eighty-three percent ended up in Asia. Europe took far less. So you might think a closed strait is Asia's problem.", 'F03', 'G13 globe: arcs from Hormuz, 83% thick to Asia, thin to Europe.', '83% TO ASIA', 'VERIFIED · EIA, 2024', 'chart grow'), ('P1-05', "It isn't. And the reason is the whole story of this winter: when Asia loses its gas, it comes shopping for yours.", '', 'Hold on globe, Asia arcs turn and point at Europe.', '', '', 'sub hit'), ('P1-06', 'On the second of March, Qatar said two Iranian drones hit its gas facilities. QatarEnergy stopped all production. The next day it declared force majeure, the legal phrase for: we cannot deliver what we promised.', 'F04 F05', "CARD-HEADLINE: recreated Bloomberg headline, 2 Mar 2026. Then CARD-QUOTE style 'FORCE MAJEURE' stamp.", 'FORCE MAJEURE · 3 MAR 2026', 'VERIFIED · Gulf News, Bloomberg', 'stamp thud'), ('P1-07', "On the eighteenth of March, Iran struck the idle complex itself. Reports put the damage at about seventeen percent of Qatar's export capacity, with repairs measured in years, not months.", 'F06', 'MAP-3D close on Ras Laffan, a red segment burns out of a ring.', '-17% CAPACITY · 3-5 YRS TO REPAIR', 'REPORTED · Reuters/Bloomberg via fuel-crisis record', 'sub_808'), ('P1-07b', "Markets felt it within days. Europe's benchmark gas price nearly doubled after the first attack, and by mid-March it was above sixty euros, from about twenty-eight in January.", 'F54 F34', 'Line chart Jan-Mar 2026, the jump marked on 2 Mar.', '€28 → €60+ (JAN-MAR 2026)', 'REPORTED · fuel-crisis record; Euronews', 'chart grow'), ('P1-08', 'And the door itself stayed shut. On the first of November 2026, the IMO counted one ship crossing Hormuz. One. Before the war, the average was eighty-five a day.', 'F09', 'G18-style bars: 85 vs 1, the 1 flickers.', '85 → 1 SHIP A DAY', 'REPORTED · IMO PortWatch, 1 Nov 2026', 'whip + card + counter'), ('P1-09', 'No Gulf gas has reached the European Union since May. And QatarEnergy has pushed its force majeure to at least the end of December 2026.', 'F08 F07', 'Calendar card: May to Dec greyed out.', 'NO GULF LNG TO THE EU SINCE MAY 2026', 'REPORTED · Bruegel via Euronews; OilPrice, 4 Nov 2026', 'tick'), ('P1-10', 'So here is the first line on your bill. In the UK, wholesale energy was forty-seven percent of the cap in October. When wholesale gas goes up, the cap follows, a few months later.', 'F39', 'RECEIPT starts printing in the corner. Line 1: WHOLESALE GAS.', 'WHOLESALE = 47% OF YOUR CAP', 'REPORTED · Ofgem via PreparedBritain', 'printer'), ('P1-10b', "Here's how that works. The cap doesn't limit your total bill. It limits the price of each unit of energy, and the daily standing charge. Ofgem resets it every three months, using what gas cost on the forward market in roughly the three months before it announces.", 'F61', 'Explainer card: a meter dial, unit price and standing charge highlighted, a 3-month window sliding along a price line.', 'CAPS THE PRICE PER UNIT, NOT YOUR BILL', 'VERIFIED · Institute for Government', 'tick'), ('P1-10d', 'So what are you actually paying for? Ofgem publishes the answer. Take the typical bill right now, one thousand seven hundred and twenty-three pounds a year. Almost half of it, forty-seven percent, is the gas and power itself, bought on the wholesale market. About a quarter is the cost of the pipes and wires that bring it to your door.', 'F70', 'Stacked bar builds: wholesale 47%, networks 24%, operating 17%, policy 6%.', 'WHOLESALE 47% · NETWORKS 24%', 'VERIFIED · Ofgem cap summary, Oct-Dec 2026', 'chart grow'), ('P1-10e', "Another seventeen percent is the supplier's running costs, including the money it loses when customers can't pay. Six percent is government policy costs. And then there's tax. Since the first of October, household electricity has carried no VAT, and that's now been extended to July 2027. Gas still carries five percent.", 'F70 F45', 'Same bar: the VAT slice for electricity empties, gas stays at 5%.', 'GAS VAT 5% · ELECTRICITY VAT 0% (TO JUL 2027)', 'VERIFIED · Ofgem; Budget 28 Oct 2026', 'tick'), ('P1-10f', "That first slice is the one that moves. The pipes cost about the same in a war as in peace. The wholesale gas does not. At the start of this year, wholesale was thirty-seven percent of the typical bill. By October, it was forty-seven. So when a plant in Qatar goes quiet, it's almost half of your bill that starts to swing.", 'F70 F82', 'Wholesale slice grows from 37% to 47% and pulses orange; the rest stays grey.', 'WHOLESALE: 37% (JAN 2026) → 47% (OCT 2026)', 'VERIFIED · Ofgem', 'sub hit'), ('P1-10g', 'The cap itself is younger than most people think. It only started on the first of January 2019. It was meant to stop loyal customers being overcharged. It was never designed for a war.', 'F75', 'Timeline card: 2019 cap begins, 2022 crisis, 2026 war.', 'PRICE CAP SINCE 1 JAN 2019', 'VERIFIED · Ofgem decision, Nov 2018', ''), ('P1-10c', "So the January cap is built from the autumn. And in late October, Europe's benchmark gas price went above a hundred euros for the first time in four years.", 'F63 F35', 'Price line Aug-Nov 2026, the window glowing over the late-October peak.', '€100+ · FIRST TIME IN 4 YEARS', 'VERIFIED · Platts, Oct 2026', 'sub hit'), ('P1-11', 'The energy price cap is one thousand, seven hundred and twenty-three pounds a year from October to December 2026. For January, Cornwall Insight forecasts one thousand, nine hundred and ninety-nine. EDF forecasts two thousand, one hundred and eighty-nine.', 'F41 F43', 'Number count-up: £1,723 → £1,999 → £2,189.', '£1,723 → £1,999-£2,189', 'VERIFIED (cap) · ESTIMATE (forecasts), Oct 2026', 'counter roll'), ('P1-12', "That's an extra twenty-three to thirty-nine pounds a month at the annual rate. And winter months use more energy than the average, so a real January bill jumps by more than that.", 'F43 maths', 'RECEIPT line 1 prints: +£23-39/mo.', '+£23 TO £39 A MONTH', 'ESTIMATE · our maths from the forecasts', 'receipt print'), ('P1-12b', "So that's the first line on the receipt. A plant in Qatar goes quiet, a strait almost empties, and the forward price of gas jumps in exactly the months Ofgem uses to set your January cap. But that's only the price. The next question is whether Europe has enough gas to get through the winter at all.", '', 'RECEIPT corner: line 1 printed; camera pushes to a storage tank icon.', 'LINE 1: THE PRICE', '', ''), ('BR-01', 'If you want the next bill before it arrives, subscribe. Our next video follows the same gas into fertilizer, and into the price of your bread.', '', 'G24 bridge card, next-video thumbnail.', 'NEXT: THE HUNGER BILL', '', 'riser air'), ('P2-01', 'Part two. The tank.', '', 's_part: PART 2, THE TANK.', 'PART 2 · THE TANK', '', 'reverse cymbal + sub drop'), ('P2-02', "Europe gets through winter on what it saved in summer. Gas is pumped underground from April to October, then pulled out when it's cold.", '', 'AI-STILL: storage site, pipes and valves in frost, slow pan. Illustration.', '', '', 'drone'), ('P2-03', "On the third of November 2026, the EU's tanks were seventy-four percent full. The five-year average for that date is about eighty-six.", 'F13', 'Tank gauge graphic fills to 74%, a ghost line at 86%.', '74% FULL · NORMAL ≈ 86%', 'REPORTED · GIE data via OilPrice, 3 Nov 2026', 'chart grow'), ('P2-04', 'A year earlier, the tanks were nearly eighty-three percent full. In 2023, almost ninety-nine. Researchers at IEEFA say this is the lowest for the time of year since records began in 2011.', 'F14', 'Three gauges side by side: 2023, 2025, 2026.', 'LOWEST SINCE RECORDS BEGAN (2011)', 'VERIFIED · Bruegel, IEEFA via Euronews', 'tick x3'), ('P2-05', "Why so low? Because refilling in summer meant buying gas at war prices, and Qatar's cargoes simply weren't there to buy.", 'F08', 'Footage STOCK: tanker at a terminal, graded.', '', '', 'whoosh'), ('P2-06', "Now the scenarios. The European grid operators' central case ends the winter at about thirty percent. Their worst case, eleven. The International Energy Agency ran a cold winter with Hormuz still shut, and got below ten.", 'F17 F16', 'Line chart: three paths falling to end-March 2027.', 'CENTRAL 30% · WORST 11% · IEA COLD <10%', 'ESTIMATE · Entsog, IEA scenarios', 'chart grow'), ('P2-06b', "Analysts at Wood Mackenzie expect seventeen to twenty percent by the end of March, and that's in a normal winter.", 'F18', 'Fourth path added to the chart.', 'WOOD MACKENZIE: 17-20% (NORMAL WINTER)', 'ESTIMATE · Euronews, Oct 2026', 'tick'), ('P2-07', "Those are scenarios, not forecasts. A mild winter changes everything. But here's the part most people miss.", 'F16', 'Hold on chart, labels tag SCENARIO.', 'SCENARIOS, NOT FORECASTS', '', 'silence beat'), ('P2-07b', "Think of storage as insurance you buy in summer and claim in winter. This year, Europe paid war prices for the policy and still couldn't buy the full cover.", 'F13 F14', 'Tank gauge with a torn insurance-policy edge.', '', '', 'whoosh'), ('P2-08', "The IEA says that once a tank drops below about thirty percent, gas comes out more slowly. The pressure falls. So a tank at twenty percent isn't a fifth of your safety. It's less.", 'F19', '2.5D: cross-section of a storage cavern, flow arrows thinning.', 'BELOW 30%, IT FLOWS SLOWER', 'VERIFIED · IEA, 3 Nov 2026', 'sub hit'), ('P2-09', "Britain is in a weaker spot again. Its storage can hold only about five percent of a year's gas use. The EU average is twenty-nine.", 'F22', 'Two bars: UK 5% vs EU 29%.', 'UK 5% · EU 29%', 'VERIFIED · UK govt via The National', 'card land'), ('P2-10', 'At the start of October, UK storage was forty-eight percent full. Portugal was at ninety-four. Poland, ninety-nine.', 'F21', 'Bars: UK 48, Portugal 94, Poland 99.', 'UK 48% · PT 94% · PL 99%', 'REPORTED · ENTSO-G via The National', 'tick'), ('P2-11a', "Now a strange fact. Britain barely buys Qatari gas. In 2025, Qatar supplied less than two percent of the UK's gas imports. Norway supplied sixty-nine percent, through pipes under the North Sea. American tankers brought three quarters of the rest as liquefied gas.", 'F57 F55 F56', 'Pie/bars: Norway 69% · US 23% · Qatar 1.8%, Qatar slice tiny and glowing orange.', 'QATAR: 1.8% OF UK GAS IMPORTS', 'VERIFIED · DESNZ DUKES 2026', 'card land'), ('P2-11b', "So why does a strait Britain hardly uses set Britain's price? Because gas is priced at the margin. Norway doesn't sell its gas cheaply to Britain just because it's next door. It sells at the European price, and the European price is set by the last cargo Europe has to fight for.", 'F55', '2.5D: a pipeline from Norway, price tag flips from cheap to the TTF number.', 'PRICED BY THE LAST CARGO', '', 'whoosh'), ('P2-11c', "And Britain needs those imports more every year. Its own North Sea production fell again in 2025, to its lowest level since 1973. The grid operator's scenarios show imports covering more than ninety percent of demand on the coldest days.", 'F58 F60', 'Line chart: UK production falling to the 1973 marker; 90% label on a cold-day bar.', 'LOWEST SINCE 1973 · 90%+ IMPORTED AT PEAK', 'VERIFIED · DUKES 2026; REPORTED · NESO', 'chart grow'), ('P2-11', 'And about half of that small British tank is one old site off the Yorkshire coast. Rough. Its owner, Centrica, says it will close at the end of the first quarter without support for a two-billion-pound rebuild.', 'F24', 'MAP-3D: North Sea, Rough glows orange.', 'ROUGH · ½ OF UK STORAGE', 'CLAIM · Centrica, Oct 2026', 'whoosh-deep'), ('P2-11d', "To see why that matters, go back to 2017. Rough was Britain's big tank then. Fully open, it held around seventy percent of all the gas storage in the country, enough for about nine days.", 'F71', 'MAP: North Sea, Rough glows, a tank icon fills to 70%.', 'ROUGH ≈ 70% OF UK STORAGE (FULLY OPEN)', 'REPORTED · Centrica via Wikipedia', ''), ('P2-11e', 'In June 2017, its owner said it was too old and too expensive to keep running, and announced it would close. The tank was empty when the next big cold snap arrived.', 'F71', 'Stamp CLOSED lands on the Rough tank, June 2017.', 'CLOSURE ANNOUNCED · JUNE 2017', 'REPORTED · Centrica via Wikipedia', 'stamp'), ('P2-11f', 'First of March 2018. The Beast from the East. Snow across Britain, and a gas system almost forty-eight million cubic metres short of what the country needed that day. National Grid issued a gas deficit warning. Within the day, the gas price hit three hundred pence a therm, a twelve-year high.', 'F74', 'Footage: snow storm; then CARD-NUMBER 300p/therm.', '1 MAR 2018 · GAS DEFICIT WARNING · 300P/THERM', 'REPORTED · National Grid via Watt-Logic', 'wind + sub hit'), ('P2-11g', "Analysts pointed at the empty space where Rough used to be. Up to forty-five million cubic metres a day that could have come out of storage, didn't exist.", 'F74', 'Gauge: a 45 mcm/day bar drawn as an empty outline.', '45 MCM/DAY MISSING', 'REPORTED · Watt-Logic', ''), ('P2-11h', "Then came 2022. Rough was partly reopened in October that year, at about a fifth of its old size. Now it's the site that might close again. Twice in ten years, Britain has had to think about winter without its biggest tank. And when the tank is small, the price of the next cargo lands straight on your bill.", 'F71', 'Timeline: 2017 closed, 2022 reopened 20%, 2027 at risk.', '2017 CLOSED · 2022 REOPENED (20%) · 2027 AT RISK', 'REPORTED', 'riser'), ('P2-12', "Then there's a second door closing. Russian liquefied gas was about a fifth of the EU's imports in the spring. From January 2027, the EU bans it.", 'F20', 'Map: a second door icon on the Baltic swings shut.', 'EU BANS RUSSIAN LNG · JAN 2027', 'REPORTED · Euronews', 'stamp'), ('P2-12b', "And the old pipeline route isn't coming back either. On the twenty-sixth of September 2022, explosions tore through the Nord Stream pipelines under the Baltic Sea. Those pipes had been built to carry Russian gas straight into Germany.", 'F81', 'MAP: Baltic, two lines from Russia to Germany break with red flashes.', 'NORD STREAM · 26 SEP 2022', 'VERIFIED · OSW, 29 Sep 2022', 'sub hit'), ('P2-12c', "So Europe lost the pipe, and now it's banning the ships from the same country. What's left is gas that comes by sea, from whoever will sell it. Every one of those cargoes can go to Europe, or to Asia. Which brings us to the auction.", 'F81', 'Map: the Baltic goes dark; ship icons appear on the Atlantic.', "WHAT'S LEFT COMES BY SEA", 'VERIFIED', 'whoosh-deep'), ('P2-13', "So halfway through, here's the running bill. On the January energy price cap, plus twenty-three to thirty-nine pounds a month. In the EU, a gas-heated home using ten thousand kilowatt hours this winter faces roughly six hundred euros more. With VAT, about seven hundred and fifteen. That's a hundred and twenty to a hundred and forty euros a month. Tell us yours in the comments: we'll read them out.", 'F43 F46', 'HALF-RECEIPT: UK and EU columns print.', 'HALF-RECEIPT', 'ESTIMATE · forecasts; analyst estimate via Euronews', 'printer'), ('P2-14', 'But that number assumes Europe can still buy the gas. The real question is: who gets the ship?', '', 'Hold on half-receipt, a ship icon with a question mark.', 'WHO GETS THE SHIP?', '', 'riser'), ('P3-01', 'Part three. The auction.', '', 's_part: PART 3, THE AUCTION.', 'PART 3 · THE AUCTION', '', 'reverse cymbal + sub drop'), ('P3-02', "Liquefied gas doesn't belong to a country until it lands. A tanker in the Atlantic can turn left for Rotterdam or right for Tokyo. It goes where someone pays more.", '', 'MAP-3D: Atlantic, one tanker, two glowing routes.', '', '', 'whoosh-deep'), ('P3-03', 'From March to October 2026, Asia was already paying more than Europe for the same gas.', 'F25 F26', 'Two lines: JKM above TTF.', 'ASIA PAYS MORE (MAR-OCT 2026)', 'VERIFIED · IEA via S&P Global', 'chart grow'), ('P3-04', "By the second of November, Asian buyers were offering close to thirty-four dollars for December cargoes, far above Europe's average. That's the price Europe has to beat to keep a ship.", 'F25', 'CARD-NUMBER: $33.91.', 'ASIA DEC LNG: $33.91', 'VERIFIED · Platts, 2 Nov 2026', 'counter'), ('P3-05', 'And Asia lost the most. Eighty-three percent of that Gulf gas used to go there. When it stopped, Asian prices jumped more than a hundred and forty percent in March.', 'F03 F27', 'Globe again: Asia arcs go dark.', 'ASIA +140% (MARCH 2026)', 'REPORTED · fuel-crisis record', 'sub_808'), ('P3-06', "In Bangladesh, four of its five fertilizer plants have been shut since March, because they run on gas that never came. That's a different bill, and we'll follow it next time.", 'F29', 'STOCK: generic factory, quiet, graded. Label Illustration if AI.', '4 OF 5 UREA PLANTS SHUT', 'REPORTED · S&P via EnterpriseAM, Oct 2026', 'drone dip'), ('P3-07', "Here's the twist. The world isn't short of everyone's gas. It's short of Gulf gas.", '', 'Typewriter text on dark.', '', '', 'type keys'), ('P3-08', 'The IEA says gas from outside the Gulf rose fourteen percent from March to October. Much of that came from one country. The United States.', 'F12', 'Bars growing: non-Gulf LNG +14%; US flag icon (no faces).', 'NON-GULF LNG +14%', 'VERIFIED · IEA, 3 Nov 2026', 'chart grow'), ('P3-09', "Even QatarEnergy, the world's biggest seller before this war, has been buying American gas to cover its own contracts.", 'F28', 'CARD-HEADLINE: recreated Reuters line.', 'QATAR BUYS US LNG', 'REPORTED · Reuters via BOE Report, 29 Oct 2026', 'stamp'), ('P3-10a', 'In October 2026, America shipped almost seven million tonnes of liquefied gas to Europe, and less than three million to Asia. It was the second-biggest month in its history. Europe is now its biggest customer.', 'F62', 'Bars: US LNG Oct 2026, Europe 6.89 mt vs Asia 2.73 mt.', 'US LNG TO EUROPE: 6.89 MT (OCT 2026)', 'REPORTED · OilPrice, 3 Nov 2026', 'chart grow'), ('P3-10', 'So in America, the bill looks different. The US Energy Information Administration expects homes heated by gas to spend nine percent less this winter. Homes on electricity, four percent more.', 'F31', 'US map split by heating fuel.', 'US GAS HEAT -9% · ELECTRIC +4%', 'VERIFIED · EIA Winter Fuels Outlook, Oct 2026', 'tick'), ('P3-11', 'But not everyone in America wins. Heating oil, used by about three percent of homes, mostly in the Northeast, is forecast thirty-four percent dearer. Their bills, up twenty-one percent.', 'F31 F32 F33', 'Map: Northeast glows red.', 'HEATING OIL +21% (NORTHEAST)', 'VERIFIED · EIA, Oct 2026', 'sub hit'), ('P3-11a', 'And then there are the countries that lose the auction. Bangladesh gets more than forty percent of its electricity from imported liquefied gas, and Qatar used to supply about ninety-five percent of it.', 'F64', 'MAP-3D: South Asia, Bangladesh and Pakistan glow orange; Qatar line dark.', 'BANGLADESH: 40%+ OF POWER FROM LNG', 'REPORTED · Reuters, Sept 2026', 'whoosh-deep'), ('P3-11b', "Spot cargoes in Asia went from about ten dollars before the war to about thirty in September. Bangladesh can't outbid Japan for a ship. So in Dhaka, one resident told Reuters she sometimes waits until midnight for enough gas to cook dinner.", 'F65 F66', 'STOCK: generic kitchen stove at night, blue flame flickering low. No faces.', '$10 → $30 (SEPT 2026)', 'REPORTED · Reuters via Al-Monitor', 'drone dip'), ('P3-11c', "In Pakistan, homes on the gas network get it in three windows a day: six to nine in the morning, twelve to three, and six to nine at night. The country needs nine cargoes for December. That's what losing the auction looks like.", 'F67 F68', 'Clock graphic with three lit windows, the rest dark.', 'GAS 6-9 · 12-3 · 6-9', 'REPORTED · The News (Pakistan), Sept 2026', 'clock tick'), ('P3-12', "So one war sends three different bills. South Asia goes without. Europe pays to outbid Asia. And America sells the gas. Britain's energy price cap is set inside that auction. Which raises the question: haven't we been here before?", '', 'Three-column receipt sketch: ASIA · EUROPE · USA.', 'ONE WAR, THREE BILLS', '', 'riser'), ('P3-12b', "So who won the auction? On paper, Europe did. It got most of America's ships. But winning an auction means paying the top price. Europe kept its tanks filling by outbidding countries that could afford it less. And that top price is exactly what rolls into Britain's cap in January.", 'F62 F25', 'Receipt columns: EUROPE column gets a WON stamp, then a price tag flips up.', 'EUROPE WON · AT THE TOP PRICE', 'VERIFIED', 'stamp'), ('P4-01', 'Part four. The last time.', '', 's_part: PART 4, THE LAST TIME.', 'PART 4 · THE LAST TIME', '', 'reverse cymbal + sub drop'), ('P4-01b', "The last time Britain's own gas fields produced this little was 1973. Back then, the North Sea was the answer to an energy crisis. Now it's running down, just as another crisis arrives.", 'F58', 'Line chart: UK production, 1973 marker glowing, line returning to it.', 'LOWEST SINCE 1973', 'VERIFIED · DUKES 2026', 'typewriter'), ('P4-01c', "1973 is worth remembering for another reason. On the sixteenth of October, the oil producers' cartel raised its price. The next day, Arab producers cut output and began an embargo on the West.", 'F76', 'Typewriter dates on dark: 16 OCT 1973 · 17 OCT 1973.', '16-17 OCTOBER 1973', 'REPORTED · MoneyWeek', 'typewriter'), ('P4-01d', 'Oil went from about three dollars a barrel to about twelve. Four times the price, in a few months. The embargo ended in March 1974. The prices did not go back.', 'F76', 'CARD-NUMBER: $3 → $12 a barrel.', '$3 → $12 A BARREL', 'REPORTED · MoneyWeek', 'counter roll'), ('P4-01e', "Britain's answer was to dig. North Sea oil and gas turned a shock into fifty years of home supply. That's the history hiding in your boiler. And it's why the end of the North Sea matters now. The last time this little gas came out of British water, the crisis made Britain build a new source. This time there isn't one waiting.", 'F58 F76', 'Footage: offshore platform, then UK production line returns to the 1973 marker.', '50 YEARS OF NORTH SEA GAS', 'VERIFIED · DUKES 2026', 'whoosh-deep'), ('P4-02', 'August 2022. Russia had cut its pipelines to Europe, and the price of gas passed three hundred and forty euros. In January 2026 it was about twenty-eight.', 'F38 F34', 'Line chart 2022 spike vs 2026, our line far below the 2022 peak.', '€340 (AUG 2022) · €28 (JAN 2026)', 'VERIFIED · Euronews', 'chart grow + sub hit'), ('P4-03', "In October 2022, Britain's price cap was set at three thousand, five hundred and forty-nine pounds. The government stepped in and held a typical bill at two thousand five hundred. About a thousand pounds less per home.", 'F52', 'CARD-NUMBER: £3,549 crossed out → £2,500.', '£3,549 → £2,500 (OCT 2022)', 'VERIFIED · Which?, Oct 2022', 'stamp'), ('P4-04', 'By September that year, governments across Europe had committed nearly five hundred billion euros to shield homes and businesses. Britain alone, a hundred and seventy-eight billion.', 'F53', 'Stacked bar: EU-27 €314bn + UK €178bn.', '≈€500 BILLION (SEPT 2022)', 'VERIFIED · Bruegel via Bloomberg', 'counter roll'), ('P4-05', "That money didn't vanish. It became public debt. Which means you're still paying the last winter, through taxes, while the next one arrives.", 'F53', "RECEIPT line: '2022 BAILOUT: STILL ON THE BILL'.", 'STILL ON THE BILL', '', 'printer'), ('P4-05b', "And it's not the only bill left over from last time. In 2021, before the war in Ukraine even started, gas prices rose so fast that small energy suppliers began to fall over. They had sold you energy at a fixed price they could no longer afford to buy.", 'F72', 'Footage: office lights switching off; then a grid of supplier logos (generic blocks) turning grey.', '2021: SUPPLIERS COLLAPSE', 'VERIFIED · National Audit Office, 2022', 'power down'), ('P4-05c', 'The National Audit Office counted twenty-eight suppliers failing from June 2021. Almost two and a half million customers were moved to new companies.', 'F72', 'Grid of 28 blocks greys out one by one.', '28 SUPPLIERS FAILED · 2.4M CUSTOMERS MOVED', 'VERIFIED · NAO', 'tick'), ('P4-05d', 'The biggest was Bulb, with one point six million customers. The government ran it through special administration, budgeting nearly two billion pounds across two years.', 'F72', 'CARD-NUMBER: Bulb 1.6M customers · £0.9bn + £1.0bn.', 'BULB: £0.9BN + £1.0BN BUDGETED', 'VERIFIED · NAO', 'counter roll'), ('P4-05e', "Ofgem estimated the failures would cost two point seven billion pounds, spread across everyone's bills. About ninety-four pounds per customer. If you paid an energy bill in 2022, you paid for companies you never used.", 'F72', 'RECEIPT line prints: SUPPLIER FAILURES ≈ £94.', '≈ £94 PER CUSTOMER', 'ESTIMATE · Ofgem via NAO', 'receipt printer'), ('P4-06', 'This time, prices are lower than 2022. On the twenty-eighth of October, the benchmark hit about a hundred and five euros, the highest since December 2022. On the fourth of November, about ninety.', 'F35 F36', 'Line chart 2026: rise to 104.90, dip to 89.59.', '€104.90 (28 OCT) · €89.59 (4 NOV)', 'VERIFIED · Platts; REPORTED · OilPrice', 'counter'), ('P4-07', "So far, Britain's only new help is zero VAT on household electricity, extended to July 2027. Nothing like 2022 has been announced. Which leaves the last question. Who feels this first?", 'F45', 'Card: 0% VAT ON ELECTRICITY → JULY 2027.', '0% VAT · ELECTRICITY', 'REPORTED · Budget, 28 Oct 2026', 'riser'), ('P4-07b', 'So the last time leaves two lessons. Help can arrive fast when a government decides to pay. And whatever it pays, households pay back later, in tax and on their bills. This time, the help is small, and the bill is still being written.', '', 'Receipt: two lines, HELP ARRIVES FAST · YOU PAY IT BACK.', 'TWO LESSONS FROM 2022', '', ''), ('P5-01', 'Part five. Your table.', '', 's_part: PART 5, YOUR TABLE.', 'PART 5 · YOUR TABLE', '', 'reverse cymbal + sub drop'), ('P5-01b', "Homes are the biggest single user of gas in Britain, about thirty-seven percent of the total. So when the price moves, it doesn't land on factories first. It lands on kitchens.", 'F59', 'Bars: domestic 37% largest; kitchen hob still.', 'HOMES: 37% OF UK GAS', 'VERIFIED · DUKES 2026', 'card land'), ('P5-01c', "And here's why that number lands so hard in Britain. At the last census, about three in every four homes in England and Wales used mains gas as their only central heating. Not a backup. The only way the radiators get warm.", 'F80', 'Footage: radiator; then a 4x4 grid of houses, 3 in 4 light orange.', '74% · MAINS GAS ONLY HEATING', 'VERIFIED · ONS Census 2021', 'tick'), ('P5-01d', "So when the gas price moves, most families can't switch to something else for the winter. They pay it, or they go cold.", 'F80', 'Footage: house lights at evening.', 'PAY IT OR GO COLD', '', ''), ('P5-02', "In England, two point three six million households were officially in fuel poverty in 2025. Seven point six million spent more than ten percent of their income on energy. That was before January's energy price cap.", 'F48', 'STOCK: apartment block at dusk (7317305), slow push.', '2.36M FUEL POOR · 7.6M SPEND >10%', 'VERIFIED · DESNZ via End Fuel Poverty Coalition', 'drone'), ('P5-03', "Campaigners at the End Fuel Poverty Coalition estimate that more than thirteen million UK households will struggle with bills in this crisis. That's their estimate, not an official count.", 'F49', 'CARD-NUMBER: 13M+ tagged CLAIM.', '13 MILLION+ HOMES', 'CLAIM · End Fuel Poverty Coalition', 'card land'), ('P5-04', "And money isn't the heaviest line on this bill. In the winter of 2022 to 2023, an estimated four thousand nine hundred and fifty excess winter deaths in the UK were caused by cold homes.", 'F50', 'Quiet: one window with frost, no people. Long hold, no music.', '4,950 (WINTER 2022/23)', 'ESTIMATE · ONS data + IHE method, via EFPC', 'silence, then single low hit'), ('P5-05', "That's an estimate, built from official death figures. But it tells you who pays first. Older people. People on prepayment meters. Anyone who turns the heating off to afford the food.", 'F50', 'Typewriter list: older people · prepay meters · heat or eat.', 'WHO PAYS FIRST', '', 'type keys'), ('P5-05b', "And many of them are already behind. Ofgem counted three point six million customers in debt or arrears on their energy bills, owing a record four point four eight billion pounds. That was before this war's winter.", 'F78', 'CARD-NUMBER: £4.48bn · 3.6M customers.', '£4.48BN OWED · 3.6M CUSTOMERS', 'VERIFIED · Ofgem, Q3 2025', 'counter roll'), ('P5-05c', 'By June 2026, the industry group Energy UK put the figure at around six billion pounds. A plan to wipe five hundred million pounds of that debt for the poorest customers has stalled, because it needs new law.', 'F79', 'Bars: £4.48bn (Q3 2025) → ~£6bn (Jun 2026); a £500m block greyed out.', '≈ £6BN (JUNE 2026) · £500M WRITE-OFF STALLED', 'REPORTED · Energy UK', 'chart grow'), ('P5-05d', "And here's the part that reaches every household. When debt goes unpaid, suppliers recover it through everyone's prices. Debt costs are already a line in the cap. So even if you pay on time, you help cover the homes that can't.", 'F78 F82', 'RECEIPT line prints: UNPAID DEBT (SHARED).', 'DEBT IS SHARED ACROSS BILLS', 'VERIFIED · Ofgem', 'receipt printer'), ('P5-06', 'In the EU, home gas already cost twelve percent more in September than in February, before the heating season even started.', 'F47', 'Bar: Feb vs Sept 2026, +12%.', '+12% FEB → SEPT 2026', 'REPORTED · HEPI via Euronews', 'chart grow'), ('P5-06b', 'And the help that exists is smaller than last time. In 2022, the government held a typical bill about a thousand pounds below the cap. So far, for this winter, the new support is zero VAT on electricity. Nothing has been announced for gas.', 'F52 F45', 'Two cards side by side: 2022 £1,000 off vs 2026 0% VAT on electricity only.', '2022: ~£1,000 OFF · 2026: 0% VAT (ELECTRICITY)', 'VERIFIED · Which?; REPORTED · Budget 28 Oct 2026', 'stamp'), ('P5-06c', "Let's put the forecasts into one household. If the cap moves from one thousand seven hundred and twenty-three pounds to the low forecast, that's two hundred and seventy-six pounds more over a year. To the high forecast, four hundred and sixty-six.", 'F42 F43', 'Household maths card: £1,723 → £1,999 = +£276; → £2,189 = +£466.', '+£276 TO +£466 A YEAR', 'ESTIMATE · our maths from forecasts', 'counter roll'), ('P5-06d', "But the January cap only lasts three months. So the bill for this winter's cold months alone is roughly sixty-nine to one hundred and seventeen pounds extra. That's the number to plan for first. And if spring prices don't fall, it carries on.", 'F42 F43', 'Calendar: JAN FEB MAR light up with +£69 to +£117.', 'JAN-MAR: +£69 TO +£117', 'ESTIMATE · our maths', ''), ('P5-07', "So here's the honest picture. What you pay in January depends on three things nobody controls: the weather, the strait, and how many ships Asia outbids you for.", '', 'Three dials: WEATHER · STRAIT · AUCTION.', '', '', 'tick x3'), ('P5-07b', "The weather is the first dial. In a normal winter, Europe's tanks end the season low but safe. In a cold one, the scenarios we showed you fall below ten percent. A cold January doesn't just make you turn the heating up. It makes every unit you burn cost more.", 'F15 F16', 'Dial 1 WEATHER turns to cold; storage gauge drops.', 'DIAL 1: THE WEATHER', 'SCENARIO · IEA / ENTSOG', 'tick'), ('P5-07c', "The strait is the second. Eighty-five ships a day used to pass through Hormuz. Now it's around one. Each day that number stays low, the gas that used to sail from Qatar has to be replaced by somebody else's.", 'F09', 'Dial 2 STRAIT: 85 → 1.', 'DIAL 2: THE STRAIT', 'REPORTED · IMO PortWatch', ''), ('P5-07d', 'And the auction is the third. As long as Asia pays more for a cargo than Europe does, the ships go east, and Europe has to raise its bid. That bid is the wholesale price. And the wholesale price is almost half of your bill.', 'F25 F70', 'Dial 3 AUCTION: JKM above TTF, arrow to RECEIPT.', 'DIAL 3: THE AUCTION', 'VERIFIED · Platts / Ofgem', ''), ('P5-07e', "Watch those three, and you'll know your January bill before Ofgem tells you.", '', 'Three dials side by side, all glowing.', 'WEATHER · STRAIT · AUCTION', '', ''), ('RC-01', 'Here is the receipt.', '', 'RECEIPT full screen, prints line by line.', 'THE RECEIPT', '', 'printer'), ('RC-02', 'Wholesale gas: plus twenty-three to thirty-nine pounds a month on the January energy price cap for a typical British home, if the forecasts hold. Plus a hundred and twenty to a hundred and forty euros a month for a gas-heated home in the EU this winter.', 'F43 F46', 'RECEIPT lines 1-2.', 'UK +£23-39/MO · EU +€120-143/MO', 'ESTIMATE · forecasts, Oct 2026', 'printer'), ('RC-02b', "In America, the receipt is shorter. Gas-heated homes, about nine percent less this winter. Heating oil in the Northeast, about twenty-one percent more. In Pakistan and Bangladesh, the line isn't money. It's hours: gas three times a day, power cuts, dinner at midnight, in countries where the minimum wage can be about a hundred and forty-five dollars a month.", 'F31 F67 F66 F69', 'RECEIPT gets two more columns: USA · SOUTH ASIA.', 'USA -9% GAS / +21% OIL · SOUTH ASIA: HOURS', 'VERIFIED · EIA; REPORTED · Reuters, The News', 'printer'), ('RC-03', 'The storage gamble: paid in time and risk, settled by the weather. The 2022 bailout: still being paid, through taxes. And the line with no price at all: the cold homes.', 'F16 F53 F50', 'RECEIPT lines 3-5, last line in crimson.', 'STORAGE · 2022 BAILOUT · COLD HOMES', '', 'printer, final line silent'), ('RC-04', "Five things you can do. Read your meter on the thirty-first of December, so January's price isn't charged on December's gas. If you can afford to, keep a small credit on your account going into the winter months.", 'F42', 'Steps list, 1-2.', '1 READ YOUR METER · 2 BUILD A SMALL CREDIT', 'General guidance, not financial advice', 'tick'), ('RC-04b', "Here's one more that costs nothing, if you have a combi boiler. Most are set to heat the water in your radiators to around eighty degrees. The innovation charity Nesta tested turning that down to sixty or below. The house still warms up, just a little slower. In 2022, Nesta put the saving at about a hundred and twelve pounds a year, at the prices back then.", 'F83', 'Footage: boiler / radiator; card 80°C → 60°C.', 'COMBI BOILER: 80°C → 60°C', 'VERIFIED · Nesta, Oct 2022', 'tick'), ('RC-04c', "It only applies to combi boilers. And if anyone at home is vulnerable to the cold, warmth comes first. A smaller bill is never worth a cold home. Check your boiler's manual, or ask an engineer to set it.", 'F83', 'Card: COMBI ONLY · WARMTH FIRST.', 'COMBI ONLY · WARMTH FIRST', 'GENERAL GUIDANCE', ''), ('RC-05', "Check what help you're entitled to before you need it. Look at fixed deals, but compare them with the new cap after the twenty-fifth of November, not before. And if you're struggling, tell your supplier early. Debt grows faster when nobody talks. And if you're outside Britain, find the date your own regulator or supplier resets prices, and read your meter the day before it does.", 'F42', 'Steps 3-5.', '3 CHECK HELP · 4 COMPARE AFTER 25 NOV · 5 TALK EARLY', 'Not financial advice', 'tick'), ('RC-05b', "Here's what that help looked like last winter, so you know what to ask about. The Warm Home Discount took a hundred and fifty pounds off the electricity bill of every household on means-tested benefits. More than six million homes.", 'F73', 'Card: £150 WARM HOME DISCOUNT · 6M+ HOMES (WINTER 2025/26).', 'WARM HOME DISCOUNT · £150', 'VERIFIED · GOV.UK, 19 June 2025', 'tick'), ('RC-05c', 'The Winter Fuel Payment went to pensioners automatically in November and December. Two hundred pounds, or three hundred if someone at home was over eighty, for those with an income of thirty-five thousand pounds or less. Check both are running this winter, and on the same terms.', 'F77', 'Card: £200 / £300 (OVER 80) · INCOME ≤ £35,000 (2025/26 RULES).', 'WINTER FUEL PAYMENT · £200-£300', 'REPORTED · 2025/26 rules', 'tick'), ('RC-05d', "And there's one thing that costs nothing. Ask your supplier to put you on its Priority Services Register if anyone at home is older, ill, or has young children. It won't lower the price. It means they have to look after you first when things go wrong.", '', 'Card: PRIORITY SERVICES REGISTER · FREE.', 'PRIORITY SERVICES REGISTER · FREE', 'GENERAL GUIDANCE', ''), ('RC-06', "This is not financial advice. It's the bill, read out loud.", '', 'Small lower-third.', 'NOT FINANCIAL ADVICE', '', ''), ('RC-07', 'Tell us in the comments: what did your last energy bill go up by? Your country, and the number.', '', 'Comment prompt card.', 'WHAT DID YOUR BILL GO UP BY?', '', ''), ('RC-07b', 'Nineteen seventy-three. Twenty eighteen. Twenty twenty-two. Twenty twenty-six. Every time, the crisis started far away, with a war, an embargo, or a storm. And every time, it ended in the same place. A number on a bill, on a kitchen table, in a home that had nothing to do with it.', 'F76 F74', 'Timeline: 1973 · 2018 · 2022 · 2026, each with its bill.', '1973 · 2018 · 2022 · 2026', '', ''), ('RC-08', 'Ras Laffan is still quiet. Somewhere in the Atlantic, a ship is deciding which way to turn. And on the twenty-fifth of November, a regulator in London will tell you which way it went.', 'F07 F42', 'Return to opening still of Ras Laffan, then the Atlantic tanker. End screen to The Hunger Bill.', 'EVERY CRISIS SENDS A BILL. HISTORY KEEPS THE RECEIPTS.', '', 'silence, then soft bed out')]
